use depot.locker;

pub fn report() -> String {
    var ax = arrive(label: "ax");
    var bay = arrive(label: "bay");
    var cod = arrive(label: "cod");

    ax = stow(locker: ax, load: 12);
    ax = stow(locker: ax, load: 9);
    bay = stow(locker: bay, load: 30);
    bay = stow(locker: bay, load: 25);
    cod = stow(locker: cod, load: 5);

    let a = ax.label.concat(other: "=").concat(other: ax.weight.to_text());
    let b = bay.label.concat(other: "=").concat(other: bay.weight.to_text());
    let c = cod.label.concat(other: "=").concat(other: cod.weight.to_text());
    a.concat(other: ",").concat(other: b).concat(other: ",").concat(other: c)
}

